const fs = require('fs');

const indexFile = fs.readFileSync('packages/frai-core/src/eval/index.test.js', 'utf8');
const toneFile = fs.readFileSync('packages/frai-core/src/eval/tone-policy.test.js', 'utf8');

// Extract the exact runEvaluations calls
const indexMatch = indexFile.match(/const evaluations = runEvaluations\(\{[^}]+outputs: \[[^\]]+\],[^}]+references: \[[^\]]+\]\s*\}\);/);
const toneMatch = toneFile.match(/const evaluations = runEvaluations\(\{[^}]+outputs: \[[^\]]+\],[^}]+references: \[[^\]]+\]\s*\}\);/);

console.log('INDEX TEST CALL:');
console.log(indexMatch ? indexMatch[0] : 'NOT FOUND');
console.log('\nTONE POLICY TEST CALL:');
console.log(toneMatch ? toneMatch[0] : 'NOT FOUND');
console.log('\nAre they identical?', indexMatch && toneMatch && indexMatch[0] === toneMatch[0]);

// Also check character by character
if (indexMatch && toneMatch) {
  const indexStr = indexMatch[0];
  const toneStr = toneMatch[0];

  console.log('\nIndex length:', indexStr.length);
  console.log('Tone length:', toneStr.length);

  if (indexStr !== toneStr) {
    for (let i = 0; i < Math.min(indexStr.length, toneStr.length); i++) {
      if (indexStr[i] !== toneStr[i]) {
        console.log(`First difference at position ${i}:`);
        console.log(`Index: "${indexStr.substring(i, i+20)}"`);
        console.log(`Tone: "${toneStr.substring(i, i+20)}"`);
        break;
      }
    }
  }
}
EOF
